<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\Task;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class TaskController extends Controller {
 public function index(Request $r){return $r->user()->tasks()->latest()->paginate(50);}
 public function store(Request $r){$d=$r->validate(['title'=>'required|string|max:180','description'=>'nullable|string|max:3000','goal_id'=>'nullable|integer|exists:goals,id','habit_id'=>'nullable|integer|exists:habits,id','priority'=>['nullable',Rule::in(['low','medium','high'])],'status'=>['nullable',Rule::in(['pending','in_progress','completed','cancelled'])],'due_at'=>'nullable|date','estimated_minutes'=>'nullable|integer|min:0|max:100000','actual_minutes'=>'nullable|integer|min:0|max:100000']);foreach(['goal_id'=>'goals','habit_id'=>'habits'] as $key=>$table){if(!empty($d[$key]))abort_unless($r->user()->{$table}()->whereKey($d[$key])->exists(),422,'Related resource must belong to your account.');}if(($d['status']??null)==='completed')$d['completed_at']=now();return response()->json($r->user()->tasks()->create($d),201);}
 public function update(Request $r,Task $task){abort_unless($task->user_id===$r->user()->id,404);$d=$r->validate(['title'=>'sometimes|required|string|max:180','description'=>'nullable|string|max:3000','priority'=>['nullable',Rule::in(['low','medium','high'])],'status'=>['nullable',Rule::in(['pending','in_progress','completed','cancelled'])],'due_at'=>'nullable|date','estimated_minutes'=>'nullable|integer|min:0|max:100000','actual_minutes'=>'nullable|integer|min:0|max:100000']);if(array_key_exists('status',$d))$d['completed_at']=$d['status']==='completed'?($task->completed_at??now()):null;$task->update($d);$t=$task->fresh();if($t->status==='completed'){$u=$r->user();\App\Support\Gamification::award($u,'task:'.$t->id,'task_completed',15);\App\Support\Gamification::badge($u,'first_task','اولین وظیفه','اولین وظیفه‌ات را تمام کردی');}return $t;}
 public function destroy(Request $r,Task $task){abort_unless($task->user_id===$r->user()->id,404);$task->delete();return response()->noContent();}
}
